{"-- Dicitura mostrata nell'app (es. \"Primo Allenatore\"); il ruolo resta la categoria generale
alter table public.staff add column if not exists qualifica text;
-- Fisioterapisti, massaggiatori, medici
alter type public.ruolo_staff add value if not exists 'staff_sanitario';"}

{"alter type public.livello_squadra add value if not exists 'serie_b2';
alter type public.livello_squadra add value if not exists 'serie_d';

insert into public.categorie_giovanili (nome, descrizione, ordine)
select v.nome, null, v.ordine
from (values ('Serie B2', 5), ('Serie D', 6)) as v(nome, ordine)
where not exists (select 1 from public.categorie_giovanili c where c.nome = v.nome);"}

{"alter table public.partite
  add column if not exists url_a3live text,
  add column if not exists parziali jsonb,
  add column if not exists stato_a3live text,
  add column if not exists letto_a3live_il timestamptz;

comment on column public.partite.url_a3live is 'Pagina della gara su a3live.federvolley.it (es. https://a3live.federvolley.it/gara/100006); letta dall''agente risultati';
comment on column public.partite.parziali is 'Parziali dei set dal nostro punto di vista: [{\"set\":1,\"nostri\":25,\"avversari\":19}, ...]';
comment on column public.partite.stato_a3live is 'Ultimo status letto sulla pagina a3live (upcoming / live / finished)';
comment on column public.partite.letto_a3live_il is 'Ultima lettura riuscita della pagina a3live';"}

{"create table public.gare_campionato (
  id uuid primary key default gen_random_uuid(),
  campionato_id uuid not null references public.campionati(id),
  stagione_id uuid references public.stagioni(id),
  girone text not null,
  numero_gara integer not null,
  giornata integer not null check (giornata between 1 and 30),
  fase text not null check (fase in ('andata','ritorno')),
  data_partita timestamptz not null,
  squadra_casa_id uuid not null references public.squadre(id),
  squadra_ospite_id uuid not null references public.squadre(id),
  partita_id uuid references public.partite(id) on delete set null,
  stato public.stato_partita not null default 'programmata',
  set_casa integer check (set_casa between 0 and 3),
  set_ospite integer check (set_ospite between 0 and 3),
  parziali jsonb,
  url_a3live text,
  fonte text default 'federvolley.it',
  creato_il timestamptz not null default now(),
  aggiornato_il timestamptz not null default now(),
  unique (campionato_id, numero_gara),
  check (squadra_casa_id <> squadra_ospite_id)
);
comment on table public.gare_campionato is 'Calendario completo del girone (tutte le gare, non solo le nostre). Fonte: calendario ufficiale federvolley.it';
comment on column public.gare_campionato.parziali is 'Parziali dal punto di vista della squadra di casa: [{\"set\":1,\"casa\":25,\"ospite\":19}, ...]';
create index gare_campionato_giornata_idx on public.gare_campionato (campionato_id, girone, giornata);
create index gare_campionato_casa_idx on public.gare_campionato (squadra_casa_id);
create index gare_campionato_ospite_idx on public.gare_campionato (squadra_ospite_id);
create index gare_campionato_partita_idx on public.gare_campionato (partita_id);
create index gare_campionato_stagione_idx on public.gare_campionato (stagione_id);
alter table public.gare_campionato enable row level security;
create policy gare_campionato_lettura_pubblica on public.gare_campionato for select using (true);
create policy gare_campionato_scrittura_staff on public.gare_campionato for all using (e_staff()) with check (e_staff());"}

{"alter table public.set_partita
  add column if not exists primo_servizio text check (primo_servizio in ('nostra', 'avversaria'));
comment on column public.set_partita.primo_servizio is 'Squadra al servizio sullo 0-0 del set (nostra/avversaria); null = regola predefinita';"}

{"alter table public.push_token
  add column if not exists notifiche_attive boolean not null default true,
  add column if not exists inizio_partita boolean not null default true,
  add column if not exists fine_set boolean not null default true,
  add column if not exists risultato_finale boolean not null default true,
  add column if not exists contenuti boolean not null default true;

comment on column public.push_token.notifiche_attive is 'Interruttore generale di Impostazioni: false = nessuna notifica';
comment on column public.push_token.inizio_partita is 'Promemoria pre-partita e inizio partita';
comment on column public.push_token.fine_set is 'Fine di ogni set (tranne quello decisivo)';
comment on column public.push_token.risultato_finale is 'Set decisivo con il risultato finale';
comment on column public.push_token.contenuti is 'Nuove news, video e podcast';

create or replace function public.preferenze_push_token(
  p_token text, p_attive boolean, p_inizio boolean, p_set boolean, p_finale boolean, p_contenuti boolean
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_token is null or p_token !~ '^Expo(nent)?PushToken\\[[^\\]]{1,200}\\]$' then
    raise exception 'Token push non valido';
  end if;
  update public.push_token
     set notifiche_attive = coalesce(p_attive, notifiche_attive),
         inizio_partita = coalesce(p_inizio, inizio_partita),
         fine_set = coalesce(p_set, fine_set),
         risultato_finale = coalesce(p_finale, risultato_finale),
         contenuti = coalesce(p_contenuti, contenuti),
         aggiornato_il = now()
   where token = p_token;
end; $$;

revoke execute on function public.preferenze_push_token(text, boolean, boolean, boolean, boolean, boolean) from public;
grant execute on function public.preferenze_push_token(text, boolean, boolean, boolean, boolean, boolean) to anon, authenticated;"}

{"-- Log dell'agente livescore (a3live): eventi leggibili da staff/admin nell'app.
-- Scrive solo l'agente con la chiave service_role (bypassa la RLS).
create table if not exists public.log_agente (
  id bigint generated always as identity primary key,
  creato_il timestamptz not null default now(),
  agente text not null,
  livello text not null default 'info' check (livello in ('info', 'avviso', 'errore')),
  evento text not null,
  partita_id uuid references public.partite(id) on delete set null,
  numero_gara integer,
  messaggio text not null,
  dettagli jsonb
);

comment on table public.log_agente is 'Eventi dell''agente livescore a3live (mac, zima): avvio, finestra aperta/chiusa, aggiornamenti scritti, battito, feed fermo, errori. Pulizia automatica dopo 60 giorni.';
comment on column public.log_agente.evento is 'avvio, stop, attesa, finestra_aperta, finestra_chiusa, aggiornamento, correzione, battito, feed_fermo, feed_ripartito, feed_mancante, errore';

create index if not exists log_agente_creato_il_idx on public.log_agente (creato_il desc);
create index if not exists log_agente_partita_idx on public.log_agente (partita_id, creato_il desc) where partita_id is not null;

alter table public.log_agente enable row level security;

drop policy if exists log_agente_lettura_staff on public.log_agente;
create policy log_agente_lettura_staff on public.log_agente
  for select to authenticated using (public.e_staff());

revoke insert, update, delete on public.log_agente from anon, authenticated;
grant select on public.log_agente to authenticated;

-- Stato sintetico: ultimo segnale di ogni agente
create or replace view public.stato_agenti with (security_invoker = on) as
select distinct on (agente)
  agente,
  creato_il as ultimo_segnale,
  evento    as ultimo_evento,
  livello   as ultimo_livello,
  messaggio as ultimo_messaggio
from public.log_agente
order by agente, creato_il desc;

revoke all on public.stato_agenti from anon;
grant select on public.stato_agenti to authenticated;

-- Realtime per la schermata admin
do $$
begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'log_agente'
  ) then
    alter publication supabase_realtime add table public.log_agente;
  end if;
end $$;

-- Pulizia giornaliera dei log oltre i 60 giorni
select cron.unschedule('pulizia-log-agente') where exists (select 1 from cron.job where jobname = 'pulizia-log-agente');
select cron.schedule('pulizia-log-agente', '30 3 * * *', $c$delete from public.log_agente where creato_il < now() - interval '60 days'$c$);
"}

{"alter table public.eventi_live add column if not exists fonte text;
comment on column public.eventi_live.fonte is 'agente = punto scritto dall''agente livescore; null = inserito dall''app';

do $$
declare
  r record;
  prev jsonb := '{}';
  prev_t jsonb := '{}';
  x jsonb; k text; n0 int; l0 int; n1 int; l1 int; dn int; dl int; fn int; fl int; tot int; i int;
  t0 timestamptz; noi_nome text; loro_nome text; in_casa boolean; chi text;
begin
  for r in
    select l.partita_id, l.creato_il, l.dettagli->'tabellone' as tab, p.casa_trasferta::text as ct
      from public.log_agente l
      join public.partite p on p.id = l.partita_id
     where l.evento in ('aggiornamento', 'correzione')
       and l.agente <> 'replay'
       and (l.dettagli->'tabellone'->>'nostra')::boolean
       and not exists (select 1 from public.eventi_live e where e.partita_id = l.partita_id and e.fonte = 'agente')
     order by l.creato_il, l.id
  loop
    k := r.partita_id::text;
    in_casa := r.ct = 'casa';
    noi_nome  := case when in_casa then r.tab->>'casa' else r.tab->>'ospite' end;
    loro_nome := case when in_casa then r.tab->>'ospite' else r.tab->>'casa' end;
    t0 := coalesce((prev_t->>k)::timestamptz, r.creato_il - interval '30 seconds');

    for x in select * from jsonb_array_elements(coalesce(r.tab->'parziali', '[]')) loop
      n1 := case when in_casa then (x->>'casa')::int else (x->>'ospite')::int end;
      l1 := case when in_casa then (x->>'ospite')::int else (x->>'casa')::int end;
      n0 := coalesce((prev->k->(x->>'set')->>0)::int, 0);
      l0 := coalesce((prev->k->(x->>'set')->>1)::int, 0);
      dn := n1 - n0; dl := l1 - l0;
      if dn >= 0 and dl >= 0 and dn + dl > 0 then
        tot := dn + dl; fn := 0; fl := 0; i := 0;
        while fn < dn or fl < dl loop
          i := i + 1;
          if fl >= dl or (fn < dn and fn * dl <= fl * dn) then
            fn := fn + 1; chi := 'nostra';
          else
            fl := fl + 1; chi := 'avversaria';
          end if;
          insert into public.eventi_live (partita_id, numero_set, punteggio_nostro, punteggio_avversario,
                                          descrizione, squadra, fonte, creato_il)
          values (r.partita_id, (x->>'set')::int, n0 + fn, l0 + fl,
                  format('Punto %s (%s-%s)', case when chi = 'nostra' then noi_nome else loro_nome end, n0 + fn, l0 + fl),
                  chi, 'agente', t0 + (r.creato_il - t0) * i / tot);
        end loop;
      end if;
      prev := jsonb_set(prev, array[k], coalesce(prev->k, '{}') || jsonb_build_object(x->>'set', jsonb_build_array(n1, l1)));
    end loop;
    prev_t := prev_t || jsonb_build_object(k, r.creato_il);
  end loop;
end $$;"}

{"do $$
begin
  if exists (select 1 from information_schema.columns
             where table_schema = 'public' and table_name = 'media' and column_name = 'etichetta_durata') then
    alter table public.media rename column etichetta_durata to etichetta;
  end if;
end $$;"}
